import sys

def count_imbalanced_people(s):
    n = len(s)
    parent_count = [0] * (n + 1)
    for i in range(1, n + 1):
        if s[i - 1] != 0:
            parent_count[s[i - 1]] += 1

    ancestors = [0] * (n + 1)
    for i in reversed(range(1, n + 1)):
        if s[i - 1] != 0:
            ancestors[i] = 1 + ancestors[s[i - 1]]

    imbalanced = 0
    for i in range(1, n + 1):
        if parent_count[i] == 2:
            left, right = 0, 0
            for j in range(1, n + 1):
                if s[j - 1] == i:
                    if left == 0:
                        left = ancestors[j]
                    else:
                        right = ancestors[j]
            if max(left, right) >= 2 * min(left, right):
                imbalanced += 1
    return imbalanced

def construct(n, k):
    if k > n // 2:
        return "NO"

    s = [0] * n
    if k == 0:
        s[0] = 1
        for i in range(1, n):
            s[i] = i + 1
        return "YES " + " ".join(map(str, s))

    s[0] = 2
    s[1] = 3
    current = 4
    imbalanced = 0
    stack = [(2, 1)]

    while imbalanced < k:
        if current > n:
            return "NO"
        parent, depth = stack.pop()
        if depth % 2 == 0:
            s[current - 1] = parent
            current += 1
            stack.append((parent, depth + 1))
            stack.append((current - 1, 1))
            imbalanced += 1
        else:
            s[current - 1] = parent
            current += 2
            stack.append((current - 2, 1))
            stack.append((current - 1, 1))

    for i in range(current - 1, n):
        s[i] = i + 1

    return "YES " + " ".join(map(str, s))

input = sys.stdin.read().strip().split()
n = int(input[0])
k = int(input[1])
print(construct(n, k))
